@'
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { loadPackageFromDirectory, validatePackage } from '@jvm-expert/core';
import { NodeFileSystem } from '@jvm-expert/node';
import { ClaudeCodeAdapter } from '@jvm-expert/adapter-claude';
import { CodexAdapter } from '@jvm-expert/adapter-codex';
const directory = resolve('skills/jvm-performance-review');
const loaded = await loadPackageFromDirectory(new NodeFileSystem(), directory, { strict: true });
const report = validatePackage(loaded.pkg, {
  strict: true, directoryName: 'jvm-performance-review',
  adapters: [new ClaudeCodeAdapter(), new CodexAdapter()],
});
const issues = [...loaded.issues, ...report.issues];
assert.deepEqual(issues, []);
assert.equal(loaded.pkg.manifest.version, '1.3.3');
const declared = new Set([
  ...(loaded.pkg.manifest.dependencies ?? []).map(item => item.name),
  ...(loaded.pkg.manifest.suggests ?? []),
]);
const referrals = new Set();
let localMarkdownLinks = 0;
for (const file of loaded.pkg.files.filter(file => file.path.endsWith('.md'))) {
  const content = readFileSync(resolve(directory, file.path), 'utf8');
  for (const match of content.matchAll(/\[[^\]]+\]\(([^)]+)\)/g)) {
    if (/^https?:/.test(match[1])) continue;
    const [target, anchor] = match[1].split('#');
    const absolute = resolve(directory, dirname(file.path), target);
    assert.ok(existsSync(absolute), file.path + ': ' + match[1]);
    if (anchor === 'one-incoming-intent-several-downstream-effects') {
      assert.ok(readFileSync(absolute, 'utf8').includes('## One incoming intent, several downstream effects'));
    }
    localMarkdownLinks++;
  }
  for (const match of content.matchAll(/`([a-z][a-z0-9]*-[a-z0-9-]+)`/g)) {
    const name = match[1];
    if (!existsSync(resolve('skills', name, 'SKILL.md'))) continue;
    assert.ok(declared.has(name), 'Undeclared referral: ' + name);
    referrals.add(name);
  }
}
console.log(JSON.stringify({
  status: 'PASS', name: loaded.pkg.manifest.name, version: loaded.pkg.manifest.version,
  files: loaded.pkg.files.length, issues: issues.length, localMarkdownLinks,
  declaredSkillReferrals: referrals.size, adapters: ['claude', 'codex'],
}));
'@ | node --input-type=module

technicalExecutions.command:
@'
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
const executable = 'C:/Users/robso/.jdks/temurin-25.0.3/bin/java.exe';
const env = {...process.env};
for (const key of Object.keys(env)) {
  if (['JAVA_TOOL_OPTIONS','JDK_JAVA_OPTIONS','_JAVA_OPTIONS'].includes(key.toUpperCase())) delete env[key];
}
const run = (name, args, additions={}) => {
  const p = spawnSync(executable, args, {env:{...env,...additions}, encoding:'utf8',timeout:10000,windowsHide:true});
  if (p.error) throw p.error;
  return {name, executable, args, environmentAdditions:additions, status:p.status,
    stdout:p.stdout, stderr:p.stderr};
};
const runs = [
 run('clean flag snapshot',['-XX:+PrintFlagsFinal','-version']),
 run('launcher-injected processor override',['-XX:+PrintFlagsFinal','-version'],{JDK_JAVA_OPTIONS:'-XX:ActiveProcessorCount=2'}),
 run('unrecognized option without masking',['-XX:+WaveReviewDefinitelyNotARealFlag','-version']),
 run('unrecognized option with masking',['-XX:+IgnoreUnrecognizedVMOptions','-XX:+WaveReviewDefinitelyNotARealFlag','-version']),
 run('documented historical ZGenerational lifecycle',['-XX:+ZGenerational','-version'])
];
assert.equal(runs[0].status,0);
assert.match(runs[0].stdout,/ActiveProcessorCount\s+=\s+-1.*\{default\}/);
assert.equal(runs[1].status,0);
assert.match(runs[1].stdout,/ActiveProcessorCount\s+=\s+2.*\{command line\}/);
assert.notEqual(runs[2].status,0);
assert.match(runs[2].stderr,/Unrecognized VM option/);
assert.equal(runs[3].status,0);
assert.equal(runs[4].status,0);
assert.match(runs[4].stderr,/Ignoring option ZGenerational; support was removed in 24.0/);
console.log(JSON.stringify({
 status:'PASS', cases:5, assertions:9, platform:process.platform, architecture:process.arch,
 removedEnvironmentVariables:['JAVA_TOOL_OPTIONS','JDK_JAVA_OPTIONS','_JAVA_OPTIONS'],
 noLiveProcessAttached:true,
 runs:runs.map(({stdout,...rest})=>({...rest,stdout:stdout.split(/\r?\n/).filter(line=>/ActiveProcessorCount/.test(line)).join('\n')}))
}));
